DECLARE raw json; plan jsonb; meal jsonb; block jsonb; item jsonb; category text; name text;
 projected jsonb; metadata jsonb; scalar jsonb; foods integer;
BEGIN
 IF source.plan_json IS NULL OR octet_length(source.plan_json)>262144 THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source content unavailable'; END IF;
 raw=source.plan_json::json;
 IF public.r12_unique_json(raw) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source content unavailable'; END IF;
 plan=raw::jsonb;
 IF public.r12_keys(plan,ARRAY['desayuno','almuerzo','comida','cena'],ARRAY['desayuno','almuerzo','comida','cena']) IS NOT TRUE THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source schema unavailable'; END IF;
 FOREACH name IN ARRAY ARRAY['desayuno','almuerzo','comida','cena'] LOOP
  meal=plan->name;
  IF meal->>'tipo_plan'='opciones' THEN
   foods=0;
   IF public.r12_keys(meal,ARRAY['kcal_objetivo','tipo_plan','proteinas','carbohidratos','grasas','vegetales'],
     ARRAY['kcal_objetivo','tipo_plan','proteinas','carbohidratos','grasas','vegetales']) IS NOT TRUE
     OR public.r12_number(meal->'kcal_objetivo') IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source options unavailable'; END IF;
   FOREACH category IN ARRAY ARRAY['proteinas','carbohidratos','grasas'] LOOP
    block=meal->category;
    IF public.r12_keys(block,ARRAY['cantidad_objetivo','opciones'],ARRAY['cantidad_objetivo','opciones']) IS NOT TRUE
     OR public.r12_number(block->'cantidad_objetivo') IS NOT TRUE OR jsonb_typeof(block->'opciones')<>'array' THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source options unavailable'; END IF;
    IF jsonb_array_length(block->'opciones')>256 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source options unavailable'; END IF;
    foods=foods+jsonb_array_length(block->'opciones');
    FOR item IN SELECT jsonb_array_elements(block->'opciones') LOOP
     IF public.r12_food(item) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source food unavailable'; END IF;
    END LOOP;
   END LOOP;
   IF jsonb_typeof(meal->'vegetales')<>'array' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source vegetables unavailable'; END IF;
   IF jsonb_array_length(meal->'vegetales')>32 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source vegetables unavailable'; END IF;
   foods=foods+jsonb_array_length(meal->'vegetales');
   FOR item IN SELECT jsonb_array_elements(meal->'vegetales') LOOP
    IF public.r12_food(item,true) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source food unavailable'; END IF;
   END LOOP;
   IF foods=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 empty meal unavailable'; END IF;
  ELSE
   IF public.r12_keys(meal,ARRAY['kcal_objetivo','kcal_real','alimentos'],ARRAY['kcal_objetivo','kcal_real','alimentos']) IS NOT TRUE
     OR public.r12_number(meal->'kcal_objetivo') IS NOT TRUE OR public.r12_number(meal->'kcal_real') IS NOT TRUE
     OR jsonb_typeof(meal->'alimentos')<>'object' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source fixed menu unavailable'; END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(meal->'alimentos')) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source foods unavailable'; END IF;
   FOR name,scalar IN SELECT key,value FROM jsonb_each(meal->'alimentos') LOOP
    IF length(name) NOT BETWEEN 1 AND 200 OR public.r12_number(scalar,true) IS NOT TRUE THEN
     RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source food unavailable'; END IF;
   END LOOP;
  END IF;
 END LOOP;
 metadata=jsonb_build_object('tmb',source.tmb,'get_total',source.get_total,'kcal_objetivo',source.kcal_objetivo,
   'kcal_real',source.kcal_real,'proteina_g',source.proteina_g,'carbs_g',source.carbs_g,'grasa_g',source.grasa_g,
   'objetivo',source.objetivo,'nivel_actividad',source.nivel_actividad,'tipo_plan',source.tipo_plan);
 FOREACH name IN ARRAY ARRAY['tmb','get_total','kcal_objetivo','kcal_real','proteina_g','carbs_g','grasa_g'] LOOP
  IF metadata->name<>'null'::jsonb AND public.r12_number(metadata->name) IS NOT TRUE THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source metadata unavailable'; END IF;
 END LOOP;
 projected=jsonb_build_object('plan',plan,'meta',metadata);
 IF octet_length(projected::text)>262144 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 projection volume unavailable'; END IF;
 RETURN projected;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
 RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R12 source content unavailable';
END

DECLARE child json;
BEGIN
 IF value IS NULL OR depth IS NULL OR depth<0 OR depth>12 THEN RETURN false; END IF;
 IF json_typeof(value)='object' THEN
  IF (SELECT count(*)<>count(DISTINCT key) FROM json_each(value)) THEN RETURN false; END IF;
  FOR child IN SELECT x.value FROM json_each(value) x LOOP
   IF public.r12_unique_json(child,depth+1) IS NOT TRUE THEN RETURN false; END IF;
  END LOOP;
 ELSIF json_typeof(value)='array' THEN
  FOR child IN SELECT json_array_elements(value) LOOP
   IF public.r12_unique_json(child,depth+1) IS NOT TRUE THEN RETURN false; END IF;
  END LOOP;
 END IF;
 RETURN true;
END

DECLARE prior public.progress_consents; linked public.client_account_links;
BEGIN
IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='R25 consent is append only'; END IF;
IF current_setting('transaction_isolation')<>'read committed' OR NEW.user_id IS DISTINCT FROM NULLIF(current_setting('app.current_tenant',true),'') OR public.r25_account(NEW.user_id) IS NOT TRUE OR (NEW.event='grant' AND public.r25_personal(NEW.user_id) IS NOT TRUE) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='R25 consent subject denied'; END IF;
PERFORM 1 FROM public.usuarios WHERE id=NEW.user_id FOR UPDATE NOWAIT;
SELECT * INTO prior FROM public.progress_consents WHERE link_id=NEW.link_id ORDER BY version DESC LIMIT 1;
IF NEW.version<>COALESCE(prior.version,0)+1 OR NEW.version>2147483647 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 consent version denied'; END IF;
IF NEW.event='withdraw' THEN
 IF prior.id IS NULL OR prior.event<>'grant' OR (NEW.link_id,NEW.gym_id,NEW.client_id,NEW.user_id,NEW.link_version,NEW.protocol,NEW.source_profile_id,NEW.share_weight,NEW.share_body_fat,NEW.share_lean_mass,NEW.share_completion,NEW.from_date,NEW.through_date)
  IS DISTINCT FROM (prior.link_id,prior.gym_id,prior.client_id,prior.user_id,prior.link_version,prior.protocol,prior.source_profile_id,prior.share_weight,prior.share_body_fat,prior.share_lean_mass,prior.share_completion,prior.from_date,prior.through_date)
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 withdrawal scope denied'; END IF;
ELSE
 SELECT * INTO linked FROM public.client_account_links WHERE id=NEW.link_id AND user_id=NEW.user_id AND gym_id=NEW.gym_id AND client_id=NEW.client_id AND status='active' AND version=NEW.link_version FOR SHARE;
 IF linked.id IS NULL OR public.r12_canonical_gym(NEW.gym_id) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 grant source denied'; END IF;
 IF NEW.source_profile_id IS NOT NULL THEN
  PERFORM 1 FROM public.clientes WHERE gym_id=NEW.user_id AND id_cliente=NEW.source_profile_id AND activo AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 personal profile denied'; END IF;
 END IF;
END IF;
NEW.created_at=clock_timestamp() AT TIME ZONE 'UTC'; RETURN NEW;
END

BEGIN
IF NEW.source_kind='legacy_unverified' THEN
 IF NEW.record_key IS NOT NULL OR NEW.measured_on IS NOT NULL OR NEW.recorded_by_id IS NOT NULL OR NEW.recorded_at IS NOT NULL OR NEW.updated_at IS NOT NULL OR NEW.withdrawn_at IS NOT NULL OR NEW.version<>1
  OR (TG_OP='UPDATE' AND OLD.source_kind<>'legacy_unverified') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 legacy provenance denied'; END IF;
 RETURN NEW;
END IF;
IF NEW.gym_id IS DISTINCT FROM NULLIF(current_setting('app.current_tenant',true),'') OR public.r25_personal(NEW.gym_id) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='R25 measurement subject denied'; END IF;
PERFORM 1 FROM public.usuarios WHERE id=NEW.gym_id FOR UPDATE NOWAIT;
PERFORM 1 FROM public.clientes WHERE gym_id=NEW.gym_id AND id_cliente=NEW.id_cliente AND activo AND deleted_at IS NULL FOR SHARE;
IF NOT FOUND OR NEW.measured_on>(clock_timestamp() AT TIME ZONE 'America/Mexico_City')::date THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 measurement source denied'; END IF;
IF TG_OP='INSERT' THEN
 IF NEW.version<>1 OR NEW.withdrawn_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 initial version denied'; END IF;
 NEW.recorded_at=clock_timestamp() AT TIME ZONE 'UTC'; NEW.updated_at=NEW.recorded_at; NEW.fecha=NEW.recorded_at;
ELSE
 IF OLD.source_kind<>'self_reported' OR OLD.withdrawn_at IS NOT NULL OR NEW.version<>OLD.version+1
  OR (NEW.id,NEW.gym_id,NEW.id_cliente,NEW.record_key,NEW.recorded_by_id,NEW.recorded_at,NEW.fecha,NEW.notas) IS DISTINCT FROM (OLD.id,OLD.gym_id,OLD.id_cliente,OLD.record_key,OLD.recorded_by_id,OLD.recorded_at,OLD.fecha,OLD.notas)
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='R25 immutable measurement denied'; END IF;
 NEW.updated_at=clock_timestamp() AT TIME ZONE 'UTC';
 IF NEW.withdrawn_at IS NOT NULL THEN NEW.withdrawn_at=NEW.updated_at; END IF;
END IF;
RETURN NEW; END
